const coreModules={soil:{navGroup:'properties',name:'흙의 분류',sub:'입도와 소성',group:'흙의 성질 / 입도·분류',words:'흙 분류 입도 세립 체분석 uscs 소성 소성도표 액성한계 소성한계 ll pl pi 모래 자갈 잔류 질량 체별 누적 통과율 유기질 AASHTO 풍화 퇴적 지질 형성 침강 비중계 미세입자 온도',questions:[['gradation','입도와 분류'],['plasticity','소성도표'],['sieve','체분석 질량'],['sedimentation','침강 입경']]},stress:{navGroup:'water',name:'유효응력',sub:'물과 흙의 하중 분담',group:'물과 응력 / 유효응력',words:'수위 물 지하수 유효응력 응력 간극수압 상재 σ',questions:[['profile','응력 분포']]},foundation:{navGroup:'foundations',name:'얕은기초',sub:'폭·하중·변형',group:'기초와 말뚝 / 얕은기초',words:'기초 폭 하중 접지압 지지력 침하 강성 탄성계수 마찰각 foundation q e φ',questions:[['pressure','접지압'],['settlement','침하'],['bearing','지지력']]}};
const defaults={...coreDefaults,...Object.fromEntries(ExtensionLabs.map(l=>[l.key,clone(l.defaults)]))};
const modules={...coreModules,...Object.fromEntries(ExtensionLabs.map(l=>[l.key,l.meta]))};
