 const field=t.dataset.field;if(field)labRegistry[state.active]?.onFieldChange?.(state.data[state.active],field,before);if(field){const range=$('controls').querySelector(`input[type=range][data-field="${field}"]`);const number=$('number-'+field);if(range&&t!==range&&val!==null)range.value=String(rangePosition(range,val));if(number&&t!==number)number.value=typeof val==='number'?String(val/Number(t.dataset.mult||1)):'';}
